export const initialShoppingList = {
  id: "list001",
  name: "Food Stuff",
  ownerId: "user123",
  currentUserId: "user123",
  members: [
    { id: "user123", name: "Kim Mariya", role: "owner" },
    { id: "user456", name: "Tik Tak", role: "member" }
  ],
  items: [
    { id: "item01", name: "Milk", isSolved: false },
    { id: "item02", name: "Bread", isSolved: true }
  ]
};
